function evidenceText(e){return norm([text(e.response_propositions),text(e.question_or_problem),text(e.conditions_or_qualifications),text(e.documented_circumstances),text(e.audience)].join(' '));}
function isYiddishHayomYomQuestion(query){const q=norm(query);return q.includes('היום יום')&&q.includes('יידיש')&&q.includes('אמת')&&q.includes('תנועה');}
function supportsYiddishHayomYomProposition(proposition){const t=norm(proposition);const truth=/(?:אמת|האמת|truth)/.test(t),search=/(?:חיפוש|לחפש|לברר|בירור|search|seek)/.test(t),examination=/(?:בדיקה|בדיקת|לבחון|בחינה|בחינת|בדוק|examine|scrutin)/.test(t),movement=/(?:תנועה|תנועות|פעולה|פעולות|מעשה|מעשים|movement|action)/.test(t);return truth&&search&&examination&&movement;}
function supportsYiddishHayomYomSource(e){return String(e?.language||'').toLowerCase()==='yiddish'&&String(e?.original_language||'').toLowerCase()==='yiddish'&&e?.has_content_evidence===true&&e?.independent_witness!==false&&!e?.translation_of_evidence_family_id&&arr(e?.response_propositions).some(supportsYiddishHayomYomProposition);}
function supportsActiveFarbrengenProposition(p){const t=norm(p);return /(?:התוועד|farbrengen)/.test(t)&&/(?:פעיל|פעילות|ממשי|להמשיכ|כל השנה|active|throughout the year|practical)/.test(t);}
function supportsStudyRoutineComparison(p){const t=norm(p);return ['זמני לימוד','קביעות עתים','ללמוד יחד עם אדם נוסף','לימוד יחד עם חבר','לימוד בצוותא'].some(term=>containsTerm(t,term));}
function supportsFarmingStudyComparison(p){const t=norm(p);return ['חקלאים ובעלי משק','עבודה במשק חקלאי','לימוד תורה לצד עבודה במשק','לימוד תורה במשק','עוסק בחקלאות ולומד תורה'].some(term=>containsTerm(t,term));}
function supportsStudyFarmingComparisonSource(e){return arr(e.response_propositions).some(p=>supportsStudyRoutineComparison(p)||supportsFarmingStudyComparison(p));}
function isHayomYomSukkotCustomsQuestion(query){const q=norm(query);return q.includes('היום יום')&&q.includes('הושענא רבה')&&q.includes('שמיני עצרת')&&q.includes('מנהג');}
function supportsHayomYomSukkotCustomsProposition(p){const t=norm(p);const hoshana=t.includes('הושענא רבה')&&['הושענות','לולב','דבש','פרשת ברכה'].some(term=>containsTerm(t,term));const shemini=t.includes('שמיני עצרת')&&['סוכה','הקפות','שמחה','המשכה'].some(term=>containsTerm(t,term));return hoshana||shemini;}
function isEducationGovernanceQuestion(query){const q=norm(query);return q.includes('אחריות הנהלות מוסדות חינוך')&&q.includes('בחינת תוצאות החינוך')&&q.includes('תיקון ליקויים');}
function supportsEducationGovernanceProposition(p){const t=norm(p);return (t.includes('ליקויים')&&t.includes('חינוך'))||(t.includes('יסודות')&&t.includes('תורה')&&t.includes('מצוות'))||(t.includes('הנהלת מוסד חינוך')&&t.includes('תוצאות החינוך'))||(t.includes('הנהלה')&&t.includes('תוצאות החינוך'))||(t.includes('בוגרים')&&t.includes('תוצאות החינוך'));}
function supportsEducationGovernanceSource(e){return arr(e.response_propositions).some(supportsEducationGovernanceProposition);}

function metadataText(e){return norm([e.title,e.search_text,e.source_class,e.date,e.language,e.original_language,e.proposition_language,e.topic,e.subtopic].join(' '));}
function requestedSourceLanguage(query){const q=norm(query);if(/(?:ביידיש|יידיש|yiddish)/.test(q))return 'yiddish';if(/(?:באנגלית|אנגלית|english)/.test(q))return 'english';if(/(?:בעברית|עברית|hebrew)/.test(q))return 'hebrew';return null;}
function overlap(t,terms){return terms.reduce((n,x)=>n+(x&&containsTerm(t,x)?1:0),0);}
function familyKey(e){return e.evidence_family_id||e.aid||e.source_url||e.key;}
function propositionKey(p){return contentWords(p).sort().join(' ');}
function sameClaim(a,b){if(propositionKey(a)===propositionKey(b))return true;if(negationSignature(a)!==negationSignature(b))return false;return jaccard(a,b)>=0.72;}
function hayomYomThoughtPrayerActionCategory(p){const t=norm(p);if(t.includes('מחשבה')&&t.includes('שכל')&&t.includes('מידות'))return 'thought_as_instrument';if(t.includes('עבודת התפילה')&&t.includes('הרגשת הלב')&&t.includes('מעשה'))return 'prayer_to_action';if(t.includes('חסרונות')&&t.includes('מעלות')&&t.includes('עבודה בפועל'))return 'self_knowledge_to_action';return null;}
